const DOTS: [number, number, number, number, number][] = RAW.split(" ").map((entry) => {
  const [x, y, r, op, shade] = entry.split(",").map(Number);
  return [x, y, r, op, shade];
});

const VIEW_W = 640;
const VIEW_H = 700;
const CX = VIEW_W / 2;
const CY = VIEW_H / 2;
const RX = (VIEW_W / 2) * 1.04;
const RY = (VIEW_H / 2) * 1.04;

const ORANGE = [255, 138, 0];
const CORAL = [242, 103, 155];
const PURPLE = [123, 92, 255];
const lerp = (a: number[], b: number[], t: number) => a.map((v, i) => Math.round(v + (b[i] - v) * t));
const baseColor = (y: number) => {
  const t = y / VIEW_H;
  return t < 0.52 ? lerp(ORANGE, CORAL, t / 0.52) : lerp(CORAL, PURPLE, (t - 0.52) / 0.48);
};

// Builds a rotated ellipse as an SVG path (two 180° elliptical arcs) rather
// than an <ellipse transform="rotate(...)">, so the exact same path can
// double as an <animateMotion> motion path via <mpath> — a transform on the
// referenced shape isn't reliably honored by SMIL motion-path computation
// across browsers, but rotation baked into the path coordinates always is.
const ellipsePath = (cx: number, cy: number, rx: number, ry: number, rotationDeg: number) => {
  const rad = (rotationDeg * Math.PI) / 180;
  const p0x = cx + rx * Math.cos(rad);
  const p0y = cy + rx * Math.sin(rad);
  const p1x = cx - rx * Math.cos(rad);
  const p1y = cy - rx * Math.sin(rad);
  return `M ${p0x} ${p0y} A ${rx} ${ry} ${rotationDeg} 0 1 ${p1x} ${p1y} A ${rx} ${ry} ${rotationDeg} 0 1 ${p0x} ${p0y}`;
};
const ring1Path = ellipsePath(CX, CY, RX * 1.22, RY * 0.3, -18);
const ring2Path = ellipsePath(CX, CY, RX * 1.1, RY * 0.22, 9);
// One dot travels a full lap of ring 1, then the other travels a full lap
// of ring 2, one at a time, looping — proportioned roughly to each ring's
// size so both dots move at a similar visual speed.
const cycleDur = 10;
const splitT = 0.55;

interface AfricaMapProps {
  className?: string;
  /** "compact": for tight app UI — no breathing pulse, no hover state.
   *  "hero": for the marketing landing page — adds a gentle breathing
   *  pulse and a hover glow. Both show the static orbit rings and their
   *  traveling gold dot. */
  variant?: "compact" | "hero";
  /** "theme" reads the surrounding app's CSS variables (--muted /
   *  --background) so the globe blends into whatever card or section it's
   *  in, in any theme (light, dark, or black) — this is the default for
   *  both variants. "dark" forces the deliberate dark-navy surface from
   *  the brand board regardless of surrounding theme, if ever needed. */
  surface?: "theme" | "dark";
  /** Explicit CSS color overrides for the sphere-surface disc and edge
   *  vignette, taking priority over `surface`. Use this when the globe
   *  sits inside a page that has its OWN local theme tokens (e.g. the
   *  marketing landing page defines its own `--card`/`--bg`, separate
   *  from the app's `hsl(var(--muted))`-style tokens) — passing those
   *  local tokens directly avoids resolving the wrong variable scope. */
  discColor?: string;
  vigColor?: string;
}

export const AfricaMap = ({ className, variant = "compact", surface, discColor, vigColor }: AfricaMapProps) => {
  const uid = useId().replace(/:/g, "");
  const discId = `globe-disc-${uid}`;
  const specId = `globe-spec-${uid}`;
  const vigId = `globe-vig-${uid}`;
  const orbitGradId = `globe-orbit-${uid}`;
  const goldGlowId = `globe-gold-${uid}`;
  const ring1Id = `globe-ring1-${uid}`;
  const ring2Id = `globe-ring2-${uid}`;
  const rootClass = `continua-globe continua-globe--${variant} ${uid}`;
  const resolvedSurface = surface ?? "theme";
  const discBase = discColor ?? (resolvedSurface === "dark" ? "#1a1f2e" : "hsl(var(--muted))");
  const vigBase = vigColor ?? (resolvedSurface === "dark" ? "#0D1117" : "hsl(var(--background))");

  return (
    <div className={[rootClass, className].filter(Boolean).join(" ")}>
      <style>{`
        .${uid} { position: relative; width: 100%; aspect-ratio: ${VIEW_W} / ${VIEW_H}; }
        .${uid} svg { display: block; width: 100%; height: 100%; overflow: visible; }
        .${uid} .globe-sphere { transform-origin: 50% 50%; transition: transform 0.6s ease, filter 0.6s ease; }
        .${uid} .globe-orbits { transform-origin: 50% 50%; opacity: 0.9; transition: opacity 0.4s ease; }
        .continua-globe--hero.${uid} .globe-sphere { animation: ${uid}-breathe 7s ease-in-out infinite; }
        .continua-globe--hero.${uid}:hover .globe-sphere,
        .continua-globe--hero.${uid}:focus-visible .globe-sphere {
          filter: drop-shadow(0 0 22px rgba(255,138,0,0.35)) drop-shadow(0 0 40px rgba(123,92,255,0.28));
        }
        .continua-globe--hero.${uid}:hover .globe-orbits { opacity: 1; }
        @keyframes ${uid}-breathe { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.018); } }
        @media (prefers-reduced-motion: reduce) {
          .${uid} .globe-sphere { animation: none !important; }
          .${uid} .orbit-traveler { display: none; }
        }
      `}</style>
      <svg viewBox={`0 0 ${VIEW_W} ${VIEW_H}`} role="img" aria-label="Dotted globe of the African continent">
        <defs>
          {/* Theme-matched sphere surface: uses the app's own --muted /
              --background tokens so it blends with whatever card or
              section it sits in, in any theme (light, dark, or black). */}
          <radialGradient id={discId} cx="36%" cy="30%" r="78%">
            <stop offset="0%" stopColor={discBase} stopOpacity="0.95" />
            <stop offset="100%" stopColor={discBase} stopOpacity="0.25" />
          </radialGradient>
          <radialGradient id={specId} cx="33%" cy="25%" r="24%">
            <stop offset="0%" stopColor="#FFFFFF" stopOpacity="0.18" />
            <stop offset="100%" stopColor="#FFFFFF" stopOpacity="0" />
          </radialGradient>
          <radialGradient id={vigId} cx="50%" cy="50%" r="50%">
            <stop offset="60%" stopColor={vigBase} stopOpacity="0" />
            <stop offset="100%" stopColor={vigBase} stopOpacity="0.55" />
          </radialGradient>
          <linearGradient id={orbitGradId} x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor="#FF8A00" stopOpacity="0.75" />
            <stop offset="50%" stopColor="#F2679B" stopOpacity="0.55" />
            <stop offset="100%" stopColor="#7B5CFF" stopOpacity="0.75" />
          </linearGradient>
          <radialGradient id={goldGlowId}>
            <stop offset="0%" stopColor="#FFD24C" stopOpacity="0.95" />
            <stop offset="60%" stopColor="#FFD24C" stopOpacity="0.35" />
            <stop offset="100%" stopColor="#FFD24C" stopOpacity="0" />
          </radialGradient>
        </defs>

        {/* Orbit rings: tilted, flattened ellipses that partially wrap the
            sphere like Saturn's rings, rather than a flat circle around a
            flat shape. Static — no rotation — each carries a single
            glowing gold dot that travels one full lap before handing off
            to the other ring's dot. */}
        <g className="globe-orbits">
          <path
            id={ring1Id} d={ring1Path}
            fill="none" stroke={`url(#${orbitGradId})`} strokeWidth="1.4"
          />
          <path
            id={ring2Id} d={ring2Path}
            fill="none" stroke={`url(#${orbitGradId})`} strokeWidth="0.9" opacity="0.6"
          />

          <g className="orbit-traveler">
            <circle r="8" fill={`url(#${goldGlowId})`} />
            <circle r="2.6" fill="#FFD24C" />
            <animateMotion dur={`${cycleDur}s`} repeatCount="indefinite" keyPoints="0;1;1" keyTimes={`0;${splitT};1`} calcMode="linear">
              <mpath href={`#${ring1Id}`} />
            </animateMotion>
            <animate attributeName="opacity" values="1;0;0" keyTimes={`0;${splitT};1`} dur={`${cycleDur}s`} calcMode="discrete" repeatCount="indefinite" />
          </g>
          <g className="orbit-traveler">
            <circle r="7" fill={`url(#${goldGlowId})`} />
            <circle r="2.2" fill="#FFD24C" />
            <animateMotion dur={`${cycleDur}s`} repeatCount="indefinite" keyPoints="0;0;1" keyTimes={`0;${splitT};1`} calcMode="linear">
              <mpath href={`#${ring2Id}`} />
            </animateMotion>
            <animate attributeName="opacity" values="0;1;1" keyTimes={`0;${splitT};1`} dur={`${cycleDur}s`} calcMode="discrete" repeatCount="indefinite" />
          </g>
        </g>

        <g className="globe-sphere">
          <ellipse cx={CX} cy={CY} rx={RX} ry={RY} fill={`url(#${discId})`} />
          {DOTS.map(([x, y, r, op, shade], i) => {
            const [cr, cg, cb] = baseColor(y);
            const sr = Math.min(255, Math.round(cr * shade));
            const sg = Math.min(255, Math.round(cg * shade));
            const sb = Math.min(255, Math.round(cb * shade));
            return <circle key={i} cx={x} cy={y} r={r} fill={`rgb(${sr},${sg},${sb})`} opacity={op} />;
          })}
          <ellipse cx={CX} cy={CY} rx={RX} ry={RY} fill={`url(#${specId})`} />
          <ellipse cx={CX} cy={CY} rx={RX} ry={RY} fill={`url(#${vigId})`} />
        </g>
      </svg>
    </div>
  );
};